import java.io.*;
import java.util.*;

public class Solution {

    static String inputString = "";
    static String[] inputLines;
    static int currentLine = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append("\n");
        }
        inputString = sb.toString();
        String[] tmp = inputString.trim().split("\n");
        inputLines = new String[tmp.length];
        for (int i = 0; i < tmp.length; i++) {
            inputLines[i] = tmp[i].trim();
        }

        solve();
    }

    static String readline() {
        return inputLines[currentLine++];
    }

    static void output(Object x) {
        String s;
        if (!(x instanceof String)) {
            s = x.toString();
        } else {
            s = (String) x;
        }
        System.out.println(s);
    }

    static void solve() {
        int N = Integer.parseInt(readline().trim());

        for (int test = 0; test < N; test++) {
            String[] fParts = readline().split(" ");
            int[] f = new int[fParts.length];
            for (int i = 0; i < fParts.length; i++) {
                f[i] = Integer.parseInt(fParts[i]);
            }
            String[] sParts = readline().split(" ");
            int[] s = new int[sParts.length];
            for (int i = 0; i < sParts.length; i++) {
                s[i] = Integer.parseInt(sParts[i]);
            }

            int result = 2;
            if (f[0] == 0 && f[1] == 0 && s[0] == 0 && s[1] == 0) {
                result = 0;
            } else if (f[0] + f[1] + s[0] + s[1] == 4) {
                result = 2;
            } else {
                result = 1;
            }

            output(result);
        }
    }
}
